#include <cstdio>
#include <inplace_vector>
#include <new>

int main() {
  std::inplace_vector<int, 2> v{1, 2};
  if (auto r = v.try_push_back(3))
    std::puts("appended");
  else
    std::puts("full");
  try {
    v.push_back(3);
  } catch (const std::bad_alloc&) {
    std::puts("bad_alloc");
  }
  std::printf("%zu\n", v.size());
