#include <cstdio>
#include <optional>
#include <ranges>

int main() {
  std::optional<int> o = 4;
  int sum = 0;
  for (int x : o | std::views::transform([](int x) { return x * 10; }))
    sum += x;
  o.reset();
  for (int x : o)
    sum += x;
  std::printf("%d\n", sum);
}

